package Controllers; import Services.OrderService; import java.io.*; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*;
@WebServlet("/ViewOrderDetailsForCustomer") public class ViewOrderDetailsForCustomer extends HttpServlet{private final OrderService s=new OrderService();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setAttribute("order",s.detail(Integer.parseInt(r.getParameter("id"))));r.getRequestDispatcher("OrderDetailsForCustomerView.jsp").forward(r,p);}}
